return ['domain'=>'flooring-calculator','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl','project-id-version'=>'Flooring Calculator for WooCommerce 1.0.7','pot-creation-date'=>'2026-10-13T20:28:13+00:00','po-revision-date'=>'2026-10-13T20:28:13+00:00','messages'=>['Flooring Calculator for WooCommerce'=>'Kalkulator podłóg dla WooCommerce','Converts between area, length and sales unit on WooCommerce product pages and shows the total price instantly. For flooring, underlay, adhesives, skirting boards, panels and profiles.'=>'Przelicza powierzchnię, długość i jednostkę sprzedaży na stronach produktów WooCommerce i od razu pokazuje cenę całkowitą. Do podłóg, podkładów, klejów, listew przypodłogowych, paneli i profili.','Patrick Schlesinger'=>'Patrick Schlesinger','https://www.cms-admins.de/'=>'https://www.cms-admins.de/','Flooring Calculator for WooCommerce needs WooCommerce to be installed and active.'=>'Kalkulator podłóg dla WooCommerce wymaga zainstalowanej i aktywnej wtyczki WooCommerce.','Quantity type'=>'Typ ilości','Coverage or container size missing'=>'Brak wydajności lub wielkości opakowania','%1$s kg/m², container %2$s kg'=>'%1$s kg/m², opakowanie %2$s kg','Size per variation'=>'Wielkość na wariant','Size per unit missing'=>'Brak wielkości na jednostkę','No change'=>'Bez zmian','Select'=>'Wybierz','Size per unit'=>'Wielkość na jednostkę','no change'=>'bez zmian','Waste (%)'=>'Zapas na docinki (%)','Set to'=>'Ustaw na','Reset to shop default'=>'Przywróć domyślne ustawienie sklepu','Shop default'=>'Domyślne ustawienie sklepu','All quantity types'=>'Wszystkie typy ilości','Quantity'=>'Ilość','equals %s'=>'to %s','How this product is measured and sold.'=>'Sposób, w jaki produkt jest mierzony i sprzedawany.','Use "Size per unit" from variations'=>'Użyj „Wielkości na jednostkę” z wariantów','The calculator uses the "Size per unit" of each variation. Useful when variations differ in size. The field below is ignored then.'=>'Kalkulator używa „Wielkości na jednostkę” każdego wariantu. Przydatne, gdy warianty różnią się wielkością. Poniższe pole jest wtedy pomijane.','Size contained in one unit of this product, for example 0.46 for 0.46 m² per pack or 8.5 for a roll of 8.5 m².'=>'Wielkość zawarta w jednej jednostce produktu, np. 0,46 dla 0,46 m² w opakowaniu lub 8,5 dla rolki 8,5 m².','Leave empty to use the shop default. 0 hides the waste checkbox for this product. Applies to area and length types.'=>'Zostaw puste, aby użyć domyślnego ustawienia sklepu. 0 ukrywa pole zapasu na docinki dla tego produktu. Dotyczy typów powierzchni i długości.','Only for the quantity type "Coverage / container". Both fields are required, otherwise the product page shows the plain quantity field.'=>'Tylko dla typu ilości „Wydajność / opakowanie”. Oba pola są wymagane, w przeciwnym razie strona produktu pokaże zwykłe pole ilości.','Coverage in kg per m²'=>'Wydajność w kg na m²','For example 1 for 1 kg per m². If the manufacturer gives a range, enter the upper value so the amount is sufficient.'=>'Np. 1 dla 1 kg na m². Jeśli producent podaje zakres, wpisz wartość górną, aby ilość wystarczyła.','Container size in kg'=>'Wielkość opakowania w kg','Content of one container, for example 10 for a 10 kg bucket.'=>'Zawartość jednego opakowania, np. 10 dla wiadra 10 kg.','Size contained in one unit of this variation, for example 1.63 for a panel of 1.63 m².'=>'Wielkość zawarta w jednej jednostce tego wariantu, np. 1,63 dla panelu 1,63 m².','Decrease amount'=>'Zmniejsz ilość','Increase amount'=>'Zwiększ ilość','Add %s%% for waste'=>'Dodaj %s%% zapasu na docinki','Calculate from room dimensions'=>'Oblicz z wymiarów pomieszczenia','Room length'=>'Długość pomieszczenia','m'=>'m','Room width'=>'Szerokość pomieszczenia','Apply'=>'Zastosuj','Total price'=>'Cena całkowita','incl. VAT'=>'z VAT','1 %1$s = %2$s %3$s'=>'1 %1$s = %2$s %3$s','Sold by the meter. Length per piece approx. %1$s %2$s.'=>'Sprzedawane na metry. Długość sztuki ok. %1$s %2$s.','Please select a product variation first.'=>'Najpierw wybierz wariant produktu.','More than %1$s %2$s are currently not available.'=>'Więcej niż %1$s %2$s jest obecnie niedostępne.','Minimum order: %1$s %2$s.'=>'Minimalne zamówienie: %1$s %2$s.','Required: %1$s %2$s'=>'Potrzeba: %1$s %2$s','Required: %1$s kg'=>'Potrzeba: %1$s kg','incl. %1$s%% waste: %2$s %3$s, %4$s %5$s'=>'z %1$s%% zapasu na docinki: %2$s %3$s, %4$s %5$s','instead of %1$s, you save %2$s'=>'zamiast %1$s, oszczędzasz %2$s','Flooring calculator'=>'Kalkulator podłóg','Settings'=>'Ustawienia','Waste for area products (%)'=>'Zapas na docinki dla produktów powierzchniowych (%)','Default the customer can add with a checkbox. Products can set their own value.'=>'Wartość domyślna, którą klient może dodać polem wyboru. Produkty mogą mieć własną wartość.','Applies to packs, rolls and panels. 0 hides the checkbox.'=>'Dotyczy opakowań, rolek i paneli. 0 ukrywa pole wyboru.','Waste for skirting and length products (%)'=>'Zapas na docinki dla listew i produktów długościowych (%)','Default for skirting boards and goods sold by the meter. Products can set their own value.'=>'Wartość domyślna dla listew przypodłogowych i towarów sprzedawanych na metry. Produkty mogą mieć własną wartość.','Applies to meters / pieces and meters. 0 hides the checkbox.'=>'Dotyczy typów metry / sztuki oraz metry. 0 ukrywa pole wyboru.','Show total price'=>'Pokaż cenę całkowitą','Show a running total below the calculator'=>'Pokaż bieżącą sumę pod kalkulatorem','Turn off if your theme already shows a running total.'=>'Wyłącz, jeśli Twój motyw już pokazuje bieżącą sumę.','Convert stock display'=>'Przelicz wyświetlanie stanu magazynowego','Show stock in the product\'s measure instead of units'=>'Pokaż stan magazynowy w mierze produktu zamiast w sztukach','"534 in stock" becomes "534.06 m² in stock". Only affects area based quantity types.'=>'„534 na stanie” zmienia się w „534,06 m² na stanie”. Dotyczy tylko typów ilości opartych na powierzchni.','Note for goods sold by the meter'=>'Uwaga dla towarów sprzedawanych na metry','Fixed text below the quantity field for the type Meters. Leave empty to show the product\'s piece length instead.'=>'Stały tekst pod polem ilości dla typu Metry. Zostaw puste, aby zamiast tego pokazać długość sztuki produktu.','Sold by the meter. Length per piece approx. 2.40 to 2.70 meters.'=>'Sprzedawane na metry. Długość sztuki ok. 2,40 do 2,70 m.','Available quantity types'=>'Dostępne typy ilości','Only the selected types appear in the product dropdown. Values already set are kept.'=>'Na liście rozwijanej produktu pojawiają się tylko wybrane typy. Już ustawione wartości zostają zachowane.','The calculator appears on a product page once a quantity type is selected and a size per unit is entered under Product data, General.'=>'Kalkulator pojawia się na stronie produktu, gdy wybrano typ ilości i wpisano wielkość na jednostkę w sekcji Dane produktu, Ogólne.','Data from a previous solution found.'=>'Znaleziono dane z poprzedniego rozwiązania.','%d field still uses an old name. The plugin takes it over on the next activation.'=>'%d pole nadal używa starej nazwy. Wtyczka przejmie je przy następnej aktywacji.' . "\0" . '%d pola nadal używają starej nazwy. Wtyczka przejmie je przy następnej aktywacji.' . "\0" . '%d pól nadal używa starej nazwy. Wtyczka przejmie je przy następnej aktywacji.','Only %s left in stock'=>'Zostało tylko %s na stanie','%s in stock'=>'%s na stanie','Square meters / packs'=>'Metry kwadratowe / opakowania','What area do you need?'=>'Jaką powierzchnię potrzebujesz?','m²'=>'m²','How many packs do you need?'=>'Ile opakowań potrzebujesz?','pack'=>'opak.','packs'=>'opak.','/&nbsp;pack'=>'/&nbsp;opak.','Area'=>'Powierzchnia','Square meters / rolls'=>'Metry kwadratowe / rolki','How many rolls do you need?'=>'Ile rolek potrzebujesz?','roll'=>'rol.','rolls'=>'rol.','/&nbsp;roll'=>'/&nbsp;rol.','Square meters / panels'=>'Metry kwadratowe / panele','How many panels do you need?'=>'Ile paneli potrzebujesz?','panel'=>'pan.','panels'=>'pan.','/&nbsp;panel'=>'/&nbsp;pan.','Calculate panels needed'=>'Oblicz potrzebną liczbę paneli','Meters / pieces'=>'Metry / sztuki','How many meters do you need?'=>'Ile metrów potrzebujesz?','How many pieces do you need?'=>'Ile sztuk potrzebujesz?','piece'=>'szt.','pieces'=>'szt.','/&nbsp;piece'=>'/&nbsp;szt.','Meters'=>'Metry','meter'=>'m','meters'=>'m','/&nbsp;meter'=>'/&nbsp;m','Coverage / container'=>'Wydajność / opakowanie','Area to be glued?'=>'Jaką powierzchnię przykleić?','How many containers do you need?'=>'Ile opakowań potrzebujesz?','container'=>'opak.','containers'=>'opak.','kg'=>'kg','/&nbsp;container'=>'/&nbsp;opak.','Weight'=>'Waga','Calculate area from room dimensions'=>'Oblicz powierzchnię z wymiarów pomieszczenia','Pieces (default)'=>'Sztuki (domyślnie)','Length'=>'Długość']];